    if (dut.u_core.fdi.sb_snd_valid !== jtagFdi_sb_snd_valid) fail($sformatf("route fdi.sb_snd_valid %0h != jtagFdi_sb_snd_valid %0h", dut.u_core.fdi.sb_snd_valid, jtagFdi_sb_snd_valid));
    if (dut.u_core.fdi.sb_snd_msg !== jtagFdi_sb_snd_msg) fail($sformatf("route fdi.sb_snd_msg %0h != jtagFdi_sb_snd_msg %0h", dut.u_core.fdi.sb_snd_msg, jtagFdi_sb_snd_msg));
