    if (dut.u_core.fdi.sb_rcv_ready !== jtagFdi_sb_rcv_ready) fail($sformatf("route fdi.sb_rcv_ready %0h != jtagFdi_sb_rcv_ready %0h", dut.u_core.fdi.sb_rcv_ready, jtagFdi_sb_rcv_ready));
    if (dut.u_core.fdi.timeout_disable !== jtagFdi_timeout_disable) fail($sformatf("route fdi.timeout_disable %0h != jtagFdi_timeout_disable %0h", dut.u_core.fdi.timeout_disable, jtagFdi_timeout_disable));
    if (dut.u_core.fdi.cycles_1us !== jtagFdi_cycles_1us) fail($sformatf("route fdi.cycles_1us %0h != jtagFdi_cycles_1us %0h", dut.u_core.fdi.cycles_1us, jtagFdi_cycles_1us));
    if (jtagFdi_fdi_pl_state_sts !== ref_fdi_pl_state_sts) fail($sformatf("lockstep jtagFdi_fdi_pl_state_sts: dut %0h, reference %0h", jtagFdi_fdi_pl_state_sts, ref_fdi_pl_state_sts));
    if (jtagFdi_fdi_pl_rx_active_req !== ref_fdi_pl_rx_active_req) fail($sformatf("lockstep jtagFdi_fdi_pl_rx_active_req: dut %0h, reference %0h", jtagFdi_fdi_pl_rx_active_req, ref_fdi_pl_rx_active_req));
