    if (jtagFdi_fdi_pl_stall_req !== ref_fdi_pl_stall_req) fail($sformatf("lockstep jtagFdi_fdi_pl_stall_req: dut %0h, reference %0h", jtagFdi_fdi_pl_stall_req, ref_fdi_pl_stall_req));
