    if (jtagFdi_fdiNeedsRdiAwake !== ref_fdiNeedsRdiAwake) fail($sformatf("lockstep jtagFdi_fdiNeedsRdiAwake: dut %0h, reference %0h", jtagFdi_fdiNeedsRdiAwake, ref_fdiNeedsRdiAwake));
    if (jtagFdi_fdiAwake !== ref_fdiAwake) fail($sformatf("lockstep jtagFdi_fdiAwake: dut %0h, reference %0h", jtagFdi_fdiAwake, ref_fdiAwake));
    if (jtagFdi_rdi_lp_stall_ack !== ref_rdi_lp_stall_ack) fail($sformatf("lockstep jtagFdi_rdi_lp_stall_ack: dut %0h, reference %0h", jtagFdi_rdi_lp_stall_ack, ref_rdi_lp_stall_ack));
