    if (jtagFdi_sb_snd_msg !== ref_sb_snd_msg) fail($sformatf("lockstep jtagFdi_sb_snd_msg: dut %0h, reference %0h", jtagFdi_sb_snd_msg, ref_sb_snd_msg));
    if (jtagFdi_sb_rcv_ready !== ref_sb_rcv_ready) fail($sformatf("lockstep jtagFdi_sb_rcv_ready: dut %0h, reference %0h", jtagFdi_sb_rcv_ready, ref_sb_rcv_ready));
  endtask

  // Output walk: force every fdi output to all-ones and random patterns
  // (clocks stopped). Block mode: each jtagFdi_* pin follows and the functional
  // outputs do not move. Functional mode: every TDR output stays 0. Covers
  // outputs that random stimulus never toggles. Run last: after release, a
  // forced register keeps its value until the block next writes it.
  UcieUPM_interfaces_pkg::PhyState_t frc_fdi_pl_state_sts;
  logic frc_fdi_pl_rx_active_req;
  logic frc_fdi_pl_inband_pres;
  logic frc_fdi_pl_wake_ack;
  logic frc_fdi_pl_clk_req;
  logic frc_fdi_pl_stall_req;
  logic frc_fdi_active;
  UcieUPM_d2dadapter_pkg::LinkInitState_t frc_debug_link_init_state;
  logic frc_rdi_lp_linkerror;
  UcieUPM_interfaces_pkg::PhyStateReq_t frc_rdi_lp_state_req;
  logic frc_fdiNeedsRdiAwake;
  logic frc_fdiAwake;
  logic frc_rdi_lp_stall_ack;
  logic frc_sb_snd_valid;
  logic [127:0] frc_sb_snd_msg;
  logic frc_sb_rcv_ready;
  task automatic output_walk(input bit blk_mode, input int unsigned patterns);
    clk_en = 0;
    #20ns;
    func_outs0 = func_outs;
    force dut.u_core.fdi.fdi_pl_state_sts = frc_fdi_pl_state_sts;
    force dut.u_core.fdi.fdi_pl_rx_active_req = frc_fdi_pl_rx_active_req;
    force dut.u_core.fdi.fdi_pl_inband_pres = frc_fdi_pl_inband_pres;
    force dut.u_core.fdi.fdi_pl_wake_ack = frc_fdi_pl_wake_ack;
    force dut.u_core.fdi.fdi_pl_clk_req = frc_fdi_pl_clk_req;
    force dut.u_core.fdi.fdi_pl_stall_req = frc_fdi_pl_stall_req;
    force dut.u_core.fdi.fdi_active = frc_fdi_active;
    force dut.u_core.fdi.debug_link_init_state = frc_debug_link_init_state;
    force dut.u_core.fdi.rdi_lp_linkerror = frc_rdi_lp_linkerror;
    force dut.u_core.fdi.rdi_lp_state_req = frc_rdi_lp_state_req;
    force dut.u_core.fdi.fdiNeedsRdiAwake = frc_fdiNeedsRdiAwake;
    force dut.u_core.fdi.fdiAwake = frc_fdiAwake;
    force dut.u_core.fdi.rdi_lp_stall_ack = frc_rdi_lp_stall_ack;
    force dut.u_core.fdi.sb_snd_valid = frc_sb_snd_valid;
    force dut.u_core.fdi.sb_snd_msg = frc_sb_snd_msg;
    force dut.u_core.fdi.sb_rcv_ready = frc_sb_rcv_ready;
    for (int unsigned k = 0; k < patterns; k++) begin
      rnd = k == 0 ? '1 : rnd_bits(); frc_fdi_pl_state_sts = type(frc_fdi_pl_state_sts)'(rnd[$bits(frc_fdi_pl_state_sts)-1:0]);
      rnd = k == 0 ? '1 : rnd_bits(); frc_fdi_pl_rx_active_req = type(frc_fdi_pl_rx_active_req)'(rnd[$bits(frc_fdi_pl_rx_active_req)-1:0]);
      rnd = k == 0 ? '1 : rnd_bits(); frc_fdi_pl_inband_pres = type(frc_fdi_pl_inband_pres)'(rnd[$bits(frc_fdi_pl_inband_pres)-1:0]);
      rnd = k == 0 ? '1 : rnd_bits(); frc_fdi_pl_wake_ack = type(frc_fdi_pl_wake_ack)'(rnd[$bits(frc_fdi_pl_wake_ack)-1:0]);
      rnd = k == 0 ? '1 : rnd_bits(); frc_fdi_pl_clk_req = type(frc_fdi_pl_clk_req)'(rnd[$bits(frc_fdi_pl_clk_req)-1:0]);
      rnd = k == 0 ? '1 : rnd_bits(); frc_fdi_pl_stall_req = type(frc_fdi_pl_stall_req)'(rnd[$bits(frc_fdi_pl_stall_req)-1:0]);
      rnd = k == 0 ? '1 : rnd_bits(); frc_fdi_active = type(frc_fdi_active)'(rnd[$bits(frc_fdi_active)-1:0]);
      rnd = k == 0 ? '1 : rnd_bits(); frc_debug_link_init_state = type(frc_debug_link_init_state)'(rnd[$bits(frc_debug_link_init_state)-1:0]);
      rnd = k == 0 ? '1 : rnd_bits(); frc_rdi_lp_linkerror = type(frc_rdi_lp_linkerror)'(rnd[$bits(frc_rdi_lp_linkerror)-1:0]);
      rnd = k == 0 ? '1 : rnd_bits(); frc_rdi_lp_state_req = type(frc_rdi_lp_state_req)'(rnd[$bits(frc_rdi_lp_state_req)-1:0]);
      rnd = k == 0 ? '1 : rnd_bits(); frc_fdiNeedsRdiAwake = type(frc_fdiNeedsRdiAwake)'(rnd[$bits(frc_fdiNeedsRdiAwake)-1:0]);
      rnd = k == 0 ? '1 : rnd_bits(); frc_fdiAwake = type(frc_fdiAwake)'(rnd[$bits(frc_fdiAwake)-1:0]);
      rnd = k == 0 ? '1 : rnd_bits(); frc_rdi_lp_stall_ack = type(frc_rdi_lp_stall_ack)'(rnd[$bits(frc_rdi_lp_stall_ack)-1:0]);
      rnd = k == 0 ? '1 : rnd_bits(); frc_sb_snd_valid = type(frc_sb_snd_valid)'(rnd[$bits(frc_sb_snd_valid)-1:0]);
      rnd = k == 0 ? '1 : rnd_bits(); frc_sb_snd_msg = type(frc_sb_snd_msg)'(rnd[$bits(frc_sb_snd_msg)-1:0]);
      rnd = k == 0 ? '1 : rnd_bits(); frc_sb_rcv_ready = type(frc_sb_rcv_ready)'(rnd[$bits(frc_sb_rcv_ready)-1:0]);
      #1ns;
      if (blk_mode) begin
        if (func_outs !== func_outs0) fail("functional output follows a forced fdi output in testModeFdi");
        check_tdr_zero(1);
        if (jtagFdi_fdi_pl_state_sts !== frc_fdi_pl_state_sts) fail($sformatf("output route: forced fdi.fdi_pl_state_sts %0h, jtagFdi_fdi_pl_state_sts %0h", frc_fdi_pl_state_sts, jtagFdi_fdi_pl_state_sts));
        if (jtagFdi_fdi_pl_rx_active_req !== frc_fdi_pl_rx_active_req) fail($sformatf("output route: forced fdi.fdi_pl_rx_active_req %0h, jtagFdi_fdi_pl_rx_active_req %0h", frc_fdi_pl_rx_active_req, jtagFdi_fdi_pl_rx_active_req));
        if (jtagFdi_fdi_pl_inband_pres !== frc_fdi_pl_inband_pres) fail($sformatf("output route: forced fdi.fdi_pl_inband_pres %0h, jtagFdi_fdi_pl_inband_pres %0h", frc_fdi_pl_inband_pres, jtagFdi_fdi_pl_inband_pres));
        if (jtagFdi_fdi_pl_wake_ack !== frc_fdi_pl_wake_ack) fail($sformatf("output route: forced fdi.fdi_pl_wake_ack %0h, jtagFdi_fdi_pl_wake_ack %0h", frc_fdi_pl_wake_ack, jtagFdi_fdi_pl_wake_ack));
        if (jtagFdi_fdi_pl_clk_req !== frc_fdi_pl_clk_req) fail($sformatf("output route: forced fdi.fdi_pl_clk_req %0h, jtagFdi_fdi_pl_clk_req %0h", frc_fdi_pl_clk_req, jtagFdi_fdi_pl_clk_req));
        if (jtagFdi_fdi_pl_stall_req !== frc_fdi_pl_stall_req) fail($sformatf("output route: forced fdi.fdi_pl_stall_req %0h, jtagFdi_fdi_pl_stall_req %0h", frc_fdi_pl_stall_req, jtagFdi_fdi_pl_stall_req));
        if (jtagFdi_fdi_active !== frc_fdi_active) fail($sformatf("output route: forced fdi.fdi_active %0h, jtagFdi_fdi_active %0h", frc_fdi_active, jtagFdi_fdi_active));
        if (jtagFdi_debug_link_init_state !== frc_debug_link_init_state) fail($sformatf("output route: forced fdi.debug_link_init_state %0h, jtagFdi_debug_link_init_state %0h", frc_debug_link_init_state, jtagFdi_debug_link_init_state));
        if (jtagFdi_rdi_lp_linkerror !== frc_rdi_lp_linkerror) fail($sformatf("output route: forced fdi.rdi_lp_linkerror %0h, jtagFdi_rdi_lp_linkerror %0h", frc_rdi_lp_linkerror, jtagFdi_rdi_lp_linkerror));
        if (jtagFdi_rdi_lp_state_req !== frc_rdi_lp_state_req) fail($sformatf("output route: forced fdi.rdi_lp_state_req %0h, jtagFdi_rdi_lp_state_req %0h", frc_rdi_lp_state_req, jtagFdi_rdi_lp_state_req));
        if (jtagFdi_fdiNeedsRdiAwake !== frc_fdiNeedsRdiAwake) fail($sformatf("output route: forced fdi.fdiNeedsRdiAwake %0h, jtagFdi_fdiNeedsRdiAwake %0h", frc_fdiNeedsRdiAwake, jtagFdi_fdiNeedsRdiAwake));
        if (jtagFdi_fdiAwake !== frc_fdiAwake) fail($sformatf("output route: forced fdi.fdiAwake %0h, jtagFdi_fdiAwake %0h", frc_fdiAwake, jtagFdi_fdiAwake));
        if (jtagFdi_rdi_lp_stall_ack !== frc_rdi_lp_stall_ack) fail($sformatf("output route: forced fdi.rdi_lp_stall_ack %0h, jtagFdi_rdi_lp_stall_ack %0h", frc_rdi_lp_stall_ack, jtagFdi_rdi_lp_stall_ack));
        if (jtagFdi_sb_snd_valid !== frc_sb_snd_valid) fail($sformatf("output route: forced fdi.sb_snd_valid %0h, jtagFdi_sb_snd_valid %0h", frc_sb_snd_valid, jtagFdi_sb_snd_valid));
        if (jtagFdi_sb_snd_msg !== frc_sb_snd_msg) fail($sformatf("output route: forced fdi.sb_snd_msg %0h, jtagFdi_sb_snd_msg %0h", frc_sb_snd_msg, jtagFdi_sb_snd_msg));
        if (jtagFdi_sb_rcv_ready !== frc_sb_rcv_ready) fail($sformatf("output route: forced fdi.sb_rcv_ready %0h, jtagFdi_sb_rcv_ready %0h", frc_sb_rcv_ready, jtagFdi_sb_rcv_ready));
      end else check_tdr_zero(0);
    end
    release dut.u_core.fdi.fdi_pl_state_sts;
    release dut.u_core.fdi.fdi_pl_rx_active_req;
    release dut.u_core.fdi.fdi_pl_inband_pres;
    release dut.u_core.fdi.fdi_pl_wake_ack;
    release dut.u_core.fdi.fdi_pl_clk_req;
    release dut.u_core.fdi.fdi_pl_stall_req;
    release dut.u_core.fdi.fdi_active;
    release dut.u_core.fdi.debug_link_init_state;
    release dut.u_core.fdi.rdi_lp_linkerror;
    release dut.u_core.fdi.rdi_lp_state_req;
    release dut.u_core.fdi.fdiNeedsRdiAwake;
    release dut.u_core.fdi.fdiAwake;
    release dut.u_core.fdi.rdi_lp_stall_ack;
    release dut.u_core.fdi.sb_snd_valid;
    release dut.u_core.fdi.sb_snd_msg;
    release dut.u_core.fdi.sb_rcv_ready;
    $display("output walk (%s): %0d patterns on 16 fdi outputs", blk_mode ? "testModeFdi" : "functional", patterns);
  endtask

  // Coverage: reference output toggles and block input bits seen at 0/1.
  int unsigned tog_fdi_pl_state_sts = 0;
  logic [$bits(jtagFdi_fdi_pl_state_sts)-1:0] last_fdi_pl_state_sts;
  int unsigned tog_fdi_pl_rx_active_req = 0;
  logic [$bits(jtagFdi_fdi_pl_rx_active_req)-1:0] last_fdi_pl_rx_active_req;
  int unsigned tog_fdi_pl_inband_pres = 0;
  logic [$bits(jtagFdi_fdi_pl_inband_pres)-1:0] last_fdi_pl_inband_pres;
  int unsigned tog_fdi_pl_wake_ack = 0;
  logic [$bits(jtagFdi_fdi_pl_wake_ack)-1:0] last_fdi_pl_wake_ack;
  int unsigned tog_fdi_pl_clk_req = 0;
  logic [$bits(jtagFdi_fdi_pl_clk_req)-1:0] last_fdi_pl_clk_req;
  int unsigned tog_fdi_pl_stall_req = 0;
  logic [$bits(jtagFdi_fdi_pl_stall_req)-1:0] last_fdi_pl_stall_req;
