  int unsigned tog_rdi_lp_linkerror = 0;
  logic [$bits(jtagFdi_rdi_lp_linkerror)-1:0] last_rdi_lp_linkerror;
  int unsigned tog_rdi_lp_state_req = 0;
  logic [$bits(jtagFdi_rdi_lp_state_req)-1:0] last_rdi_lp_state_req;
  int unsigned tog_fdiNeedsRdiAwake = 0;
  logic [$bits(jtagFdi_fdiNeedsRdiAwake)-1:0] last_fdiNeedsRdiAwake;
  int unsigned tog_fdiAwake = 0;
  logic [$bits(jtagFdi_fdiAwake)-1:0] last_fdiAwake;
  int unsigned tog_rdi_lp_stall_ack = 0;
  logic [$bits(jtagFdi_rdi_lp_stall_ack)-1:0] last_rdi_lp_stall_ack;
  int unsigned tog_sb_snd_valid = 0;
  logic [$bits(jtagFdi_sb_snd_valid)-1:0] last_sb_snd_valid;
  int unsigned tog_sb_snd_msg = 0;
  logic [$bits(jtagFdi_sb_snd_msg)-1:0] last_sb_snd_msg;
  int unsigned tog_sb_rcv_ready = 0;
  logic [$bits(jtagFdi_sb_rcv_ready)-1:0] last_sb_rcv_ready;
  logic [$bits(jtagFdi_fdi_lp_state_req)-1:0] seen0_fdi_lp_state_req = '0, seen1_fdi_lp_state_req = '0;
  logic [$bits(jtagFdi_fdi_lp_linkerror)-1:0] seen0_fdi_lp_linkerror = '0, seen1_fdi_lp_linkerror = '0;
  logic [$bits(jtagFdi_fdi_lp_rx_active_sts)-1:0] seen0_fdi_lp_rx_active_sts = '0, seen1_fdi_lp_rx_active_sts = '0;
  logic [$bits(jtagFdi_fdi_lp_wake_req)-1:0] seen0_fdi_lp_wake_req = '0, seen1_fdi_lp_wake_req = '0;
  logic [$bits(jtagFdi_fdi_lp_clk_ack)-1:0] seen0_fdi_lp_clk_ack = '0, seen1_fdi_lp_clk_ack = '0;
  logic [$bits(jtagFdi_fdi_lp_stall_ack)-1:0] seen0_fdi_lp_stall_ack = '0, seen1_fdi_lp_stall_ack = '0;
  logic [$bits(jtagFdi_rdi_pl_state_sts)-1:0] seen0_rdi_pl_state_sts = '0, seen1_rdi_pl_state_sts = '0;
  logic [$bits(jtagFdi_rdi_pl_inband_pres)-1:0] seen0_rdi_pl_inband_pres = '0, seen1_rdi_pl_inband_pres = '0;
  logic [$bits(jtagFdi_rdiAwake)-1:0] seen0_rdiAwake = '0, seen1_rdiAwake = '0;
  logic [$bits(jtagFdi_rdiNeedsFdiAwake)-1:0] seen0_rdiNeedsFdiAwake = '0, seen1_rdiNeedsFdiAwake = '0;
  logic [$bits(jtagFdi_rdi_pl_stall_req)-1:0] seen0_rdi_pl_stall_req = '0, seen1_rdi_pl_stall_req = '0;
  logic [$bits(jtagFdi_sb_snd_ready)-1:0] seen0_sb_snd_ready = '0, seen1_sb_snd_ready = '0;
  logic [$bits(jtagFdi_sb_rcv_valid)-1:0] seen0_sb_rcv_valid = '0, seen1_sb_rcv_valid = '0;
  logic [$bits(jtagFdi_sb_rcv_msg)-1:0] seen0_sb_rcv_msg = '0, seen1_sb_rcv_msg = '0;
  logic [$bits(jtagFdi_timeout_disable)-1:0] seen0_timeout_disable = '0, seen1_timeout_disable = '0;
  logic [$bits(jtagFdi_cycles_1us)-1:0] seen0_cycles_1us = '0, seen1_cycles_1us = '0;
  task automatic sample_coverage(input bit first);
    if (!first && ref_fdi_pl_state_sts !== last_fdi_pl_state_sts) tog_fdi_pl_state_sts++;
    last_fdi_pl_state_sts = ref_fdi_pl_state_sts;
    if (!first && ref_fdi_pl_rx_active_req !== last_fdi_pl_rx_active_req) tog_fdi_pl_rx_active_req++;
    last_fdi_pl_rx_active_req = ref_fdi_pl_rx_active_req;
    if (!first && ref_fdi_pl_inband_pres !== last_fdi_pl_inband_pres) tog_fdi_pl_inband_pres++;
    last_fdi_pl_inband_pres = ref_fdi_pl_inband_pres;
    if (!first && ref_fdi_pl_wake_ack !== last_fdi_pl_wake_ack) tog_fdi_pl_wake_ack++;
    last_fdi_pl_wake_ack = ref_fdi_pl_wake_ack;
    if (!first && ref_fdi_pl_clk_req !== last_fdi_pl_clk_req) tog_fdi_pl_clk_req++;
    last_fdi_pl_clk_req = ref_fdi_pl_clk_req;
    if (!first && ref_fdi_pl_stall_req !== last_fdi_pl_stall_req) tog_fdi_pl_stall_req++;
    last_fdi_pl_stall_req = ref_fdi_pl_stall_req;
    if (!first && ref_fdi_active !== last_fdi_active) tog_fdi_active++;
    last_fdi_active = ref_fdi_active;
    if (!first && ref_debug_link_init_state !== last_debug_link_init_state) tog_debug_link_init_state++;
    last_debug_link_init_state = ref_debug_link_init_state;
    if (!first && ref_rdi_lp_linkerror !== last_rdi_lp_linkerror) tog_rdi_lp_linkerror++;
    last_rdi_lp_linkerror = ref_rdi_lp_linkerror;
    if (!first && ref_rdi_lp_state_req !== last_rdi_lp_state_req) tog_rdi_lp_state_req++;
    last_rdi_lp_state_req = ref_rdi_lp_state_req;
    if (!first && ref_fdiNeedsRdiAwake !== last_fdiNeedsRdiAwake) tog_fdiNeedsRdiAwake++;
    last_fdiNeedsRdiAwake = ref_fdiNeedsRdiAwake;
    if (!first && ref_fdiAwake !== last_fdiAwake) tog_fdiAwake++;
    last_fdiAwake = ref_fdiAwake;
    if (!first && ref_rdi_lp_stall_ack !== last_rdi_lp_stall_ack) tog_rdi_lp_stall_ack++;
    last_rdi_lp_stall_ack = ref_rdi_lp_stall_ack;
    if (!first && ref_sb_snd_valid !== last_sb_snd_valid) tog_sb_snd_valid++;
    last_sb_snd_valid = ref_sb_snd_valid;
    if (!first && ref_sb_snd_msg !== last_sb_snd_msg) tog_sb_snd_msg++;
    last_sb_snd_msg = ref_sb_snd_msg;
    if (!first && ref_sb_rcv_ready !== last_sb_rcv_ready) tog_sb_rcv_ready++;
    last_sb_rcv_ready = ref_sb_rcv_ready;
    seen0_fdi_lp_state_req |= ~jtagFdi_fdi_lp_state_req; seen1_fdi_lp_state_req |= jtagFdi_fdi_lp_state_req;
    seen0_fdi_lp_linkerror |= ~jtagFdi_fdi_lp_linkerror; seen1_fdi_lp_linkerror |= jtagFdi_fdi_lp_linkerror;
    seen0_fdi_lp_rx_active_sts |= ~jtagFdi_fdi_lp_rx_active_sts; seen1_fdi_lp_rx_active_sts |= jtagFdi_fdi_lp_rx_active_sts;
    seen0_fdi_lp_wake_req |= ~jtagFdi_fdi_lp_wake_req; seen1_fdi_lp_wake_req |= jtagFdi_fdi_lp_wake_req;
    seen0_fdi_lp_clk_ack |= ~jtagFdi_fdi_lp_clk_ack; seen1_fdi_lp_clk_ack |= jtagFdi_fdi_lp_clk_ack;
    seen0_fdi_lp_stall_ack |= ~jtagFdi_fdi_lp_stall_ack; seen1_fdi_lp_stall_ack |= jtagFdi_fdi_lp_stall_ack;
    seen0_rdi_pl_state_sts |= ~jtagFdi_rdi_pl_state_sts; seen1_rdi_pl_state_sts |= jtagFdi_rdi_pl_state_sts;
    seen0_rdi_pl_inband_pres |= ~jtagFdi_rdi_pl_inband_pres; seen1_rdi_pl_inband_pres |= jtagFdi_rdi_pl_inband_pres;
    seen0_rdiAwake |= ~jtagFdi_rdiAwake; seen1_rdiAwake |= jtagFdi_rdiAwake;
    seen0_rdiNeedsFdiAwake |= ~jtagFdi_rdiNeedsFdiAwake; seen1_rdiNeedsFdiAwake |= jtagFdi_rdiNeedsFdiAwake;
    seen0_rdi_pl_stall_req |= ~jtagFdi_rdi_pl_stall_req; seen1_rdi_pl_stall_req |= jtagFdi_rdi_pl_stall_req;
    seen0_sb_snd_ready |= ~jtagFdi_sb_snd_ready; seen1_sb_snd_ready |= jtagFdi_sb_snd_ready;
    seen0_sb_rcv_valid |= ~jtagFdi_sb_rcv_valid; seen1_sb_rcv_valid |= jtagFdi_sb_rcv_valid;
    seen0_sb_rcv_msg |= ~jtagFdi_sb_rcv_msg; seen1_sb_rcv_msg |= jtagFdi_sb_rcv_msg;
    seen0_timeout_disable |= ~jtagFdi_timeout_disable; seen1_timeout_disable |= jtagFdi_timeout_disable;
    seen0_cycles_1us |= ~jtagFdi_cycles_1us; seen1_cycles_1us |= jtagFdi_cycles_1us;
  endtask

  task automatic report_coverage();
    int unsigned toggled = 0, inputs_full = 0;
    string never = "", partial = "";
    if (tog_fdi_pl_state_sts != 0) toggled++; else never = {never, " jtagFdi_fdi_pl_state_sts"};
    if (tog_fdi_pl_rx_active_req != 0) toggled++; else never = {never, " jtagFdi_fdi_pl_rx_active_req"};
    if (tog_fdi_pl_inband_pres != 0) toggled++; else never = {never, " jtagFdi_fdi_pl_inband_pres"};
    if (tog_fdi_pl_wake_ack != 0) toggled++; else never = {never, " jtagFdi_fdi_pl_wake_ack"};
    if (tog_fdi_pl_clk_req != 0) toggled++; else never = {never, " jtagFdi_fdi_pl_clk_req"};
    if (tog_fdi_pl_stall_req != 0) toggled++; else never = {never, " jtagFdi_fdi_pl_stall_req"};
    if (tog_fdi_active != 0) toggled++; else never = {never, " jtagFdi_fdi_active"};
    if (tog_debug_link_init_state != 0) toggled++; else never = {never, " jtagFdi_debug_link_init_state"};
    if (tog_rdi_lp_linkerror != 0) toggled++; else never = {never, " jtagFdi_rdi_lp_linkerror"};
    if (tog_rdi_lp_state_req != 0) toggled++; else never = {never, " jtagFdi_rdi_lp_state_req"};
    if (tog_fdiNeedsRdiAwake != 0) toggled++; else never = {never, " jtagFdi_fdiNeedsRdiAwake"};
    if (tog_fdiAwake != 0) toggled++; else never = {never, " jtagFdi_fdiAwake"};
    if (tog_rdi_lp_stall_ack != 0) toggled++; else never = {never, " jtagFdi_rdi_lp_stall_ack"};
    if (tog_sb_snd_valid != 0) toggled++; else never = {never, " jtagFdi_sb_snd_valid"};
    if (tog_sb_snd_msg != 0) toggled++; else never = {never, " jtagFdi_sb_snd_msg"};
    if (tog_sb_rcv_ready != 0) toggled++; else never = {never, " jtagFdi_sb_rcv_ready"};
    if (&seen0_fdi_lp_state_req && &seen1_fdi_lp_state_req) inputs_full++; else partial = {partial, " jtagFdi_fdi_lp_state_req"};
    if (&seen0_fdi_lp_linkerror && &seen1_fdi_lp_linkerror) inputs_full++; else partial = {partial, " jtagFdi_fdi_lp_linkerror"};
    if (&seen0_fdi_lp_rx_active_sts && &seen1_fdi_lp_rx_active_sts) inputs_full++; else partial = {partial, " jtagFdi_fdi_lp_rx_active_sts"};
    if (&seen0_fdi_lp_wake_req && &seen1_fdi_lp_wake_req) inputs_full++; else partial = {partial, " jtagFdi_fdi_lp_wake_req"};
    if (&seen0_fdi_lp_clk_ack && &seen1_fdi_lp_clk_ack) inputs_full++; else partial = {partial, " jtagFdi_fdi_lp_clk_ack"};
    if (&seen0_fdi_lp_stall_ack && &seen1_fdi_lp_stall_ack) inputs_full++; else partial = {partial, " jtagFdi_fdi_lp_stall_ack"};
    if (&seen0_rdi_pl_state_sts && &seen1_rdi_pl_state_sts) inputs_full++; else partial = {partial, " jtagFdi_rdi_pl_state_sts"};
    if (&seen0_rdi_pl_inband_pres && &seen1_rdi_pl_inband_pres) inputs_full++; else partial = {partial, " jtagFdi_rdi_pl_inband_pres"};
    if (&seen0_rdiAwake && &seen1_rdiAwake) inputs_full++; else partial = {partial, " jtagFdi_rdiAwake"};
    if (&seen0_rdiNeedsFdiAwake && &seen1_rdiNeedsFdiAwake) inputs_full++; else partial = {partial, " jtagFdi_rdiNeedsFdiAwake"};
    if (&seen0_rdi_pl_stall_req && &seen1_rdi_pl_stall_req) inputs_full++; else partial = {partial, " jtagFdi_rdi_pl_stall_req"};
    if (&seen0_sb_snd_ready && &seen1_sb_snd_ready) inputs_full++; else partial = {partial, " jtagFdi_sb_snd_ready"};
    if (&seen0_sb_rcv_valid && &seen1_sb_rcv_valid) inputs_full++; else partial = {partial, " jtagFdi_sb_rcv_valid"};
    if (&seen0_sb_rcv_msg && &seen1_sb_rcv_msg) inputs_full++; else partial = {partial, " jtagFdi_sb_rcv_msg"};
    if (&seen0_timeout_disable && &seen1_timeout_disable) inputs_full++; else partial = {partial, " jtagFdi_timeout_disable"};
    if (&seen0_cycles_1us && &seen1_cycles_1us) inputs_full++; else partial = {partial, " jtagFdi_cycles_1us"};
    $display("testModeFdi: %0d of 16 block outputs toggled, %0d of 16 block inputs saw every bit at 0 and 1", toggled, inputs_full);
    if (never != "" && toggled + 12 >= 16) $display("  outputs never toggled (route checked by the output walk):%s", never);
    else if (never != "") $display("  %0d outputs never toggled (routes checked by the output walk)", 16 - toggled);
    if (partial != "") fail({"block inputs not fully exercised:", partial});
    if (toggled == 0) fail("no block output ever toggled: fdi is not running in testModeFdi");
  endtask

  // ---------------------------------------------------------------------
  // Phases. Mode pins change only while every clock is stopped.
  // ---------------------------------------------------------------------
  task automatic run_phase(input phase_t ph, input int unsigned cycles);
    clk_en = 0;
    #20ns;
    phase = ph;
    testModeFdi = (ph == PH_BLK);
    for (cycle = 0; cycle < cycles; cycle++) begin
      @(negedge tb_clk);
      if (cycle == 0) clk_en = 1;
      if (cycle > RESET_CYCLES) begin
        check_shadow();
        if (ph == PH_FUNC) check_tdr_zero(0);
        else begin
          if (cycle == RESET_CYCLES + 1) func_outs0 = func_outs;
          check_tdr_zero(1);
          check_block();
          sample_coverage(cycle == RESET_CYCLES + 1);
        end
      end
      drive(cycle);
    end
    clk_en = 0;
    $display("%s phase done: %0d cycles", ph == PH_BLK ? "testModeFdi" : "functional", cycles);
  endtask

  initial begin : run_test
    int unsigned seed, blk_cycles;
    seed = 1;
    blk_cycles = 20000;
    void'($value$plusargs("SEED=%d", seed));
    void'($value$plusargs("CYCLES=%d", blk_cycles));
    void'($urandom(seed));
    $display("UcieDigitalTopTestModeFdiSpec_tb: seed %0d, testModeFdi phase %0d cycles", seed, blk_cycles);
    testModeDigital = 1'b0;
    testModeFdi = 1'b0;
    testModeLtsm = 1'b0;
    testModePhy = 1'b0;
    testModeRdi = 1'b0;
    zero_inputs();
    run_phase(PH_FUNC, FUNC_CYCLES);
    run_phase(PH_BLK, blk_cycles);
    run_phase(PH_FUNC, FUNC_CYCLES);
    output_walk(0, 8);
    phase = PH_BLK;
    testModeFdi = 1'b1;
    output_walk(1, 8);
    report_coverage();
    if (errors != 0) $fatal(1, "FAIL: %0d errors", errors);
    $display("PASS: testModeFdi: fdi routed to jtagFdi_* pins, matches reference, rest of the top isolated");
    $finish;
  end
endmodule

`default_nettype wire
